#!/usr/bin/env python3
"""GitHub Action: PR Review with Claude.

Posts a structured Markdown review comment on the PR.
Run as a GitHub Action step, not standalone.

Required env vars:
  GITHUB_TOKEN      — GitHub Actions token (auto-provided)
  ANTHROPIC_API_KEY — Anthropic API key
  PR_NUMBER         — PR number (auto from GitHub Actions context)
  PR_REPO           — PR source repo owner/name (auto from GitHub Actions context)
"""

import json
import os
import sys
import urllib.request
import urllib.error


def fetch_diff(repo: str, number: int, token: str) -> str:
    """Fetch unified diff for a PR."""
    url = f"https://api.github.com/repos/{repo}/pulls/{number}"
    req = urllib.request.Request(url, headers={
        "Accept": "application/vnd.github.v3.diff",
        "User-Agent": "claude-review-action/1.0",
        "Authorization": f"Bearer {token}",
    })
    with urllib.request.urlopen(req, timeout=30) as resp:
        return resp.read().decode("utf-8")


def call_claude(diff_text: str) -> dict:
    """Call Claude API."""
    api_key = os.environ["ANTHROPIC_API_KEY"]
    prompt = (
        "You are an experienced senior software engineer reviewing a pull request.\n"
        "Analyze the following diff and return ONLY a JSON object with these keys:\n"
        '- "summary": string, 2-3 sentences summarizing the changes\n'
        '- "risks": array of strings, identified risks or concerns\n'
        '- "suggestions": array of strings, improvement suggestions\n'
        '- "confidence": one of "Low", "Medium", "High"\n\n'
        f"Diff:\n---\n{diff_text[:50000]}\n---"
    )

    data = json.dumps({
        "model": "claude-sonnet-4-20250514",
        "max_tokens": 4096,
        "system": "Review the PR diff. Be specific, reference actual files. Distinguish critical issues from nitpicks.",
        "messages": [{"role": "user", "content": prompt}],
    }).encode("utf-8")

    req = urllib.request.Request(
        "https://api.anthropic.com/v1/messages",
        data=data,
        headers={
            "Content-Type": "application/json",
            "x-api-key": api_key,
            "anthropic-version": "2023-06-01",
        },
    )

    with urllib.request.urlopen(req, timeout=120) as resp:
        result = json.loads(resp.read().decode("utf-8"))
        content = result["content"][0]["text"]
        if "```" in content:
            content = content.split("```")[1]
            if content.startswith("json"):
                content = content[4:]
        return json.loads(content.strip())


def post_comment(repo: str, number: int, token: str, review: dict):
    """Post review as a PR comment."""
    risks = "\n".join(f"- {r}" for r in review.get("risks", [])) or "- None identified"
    suggestions = "\n".join(f"- {s}" for s in review.get("suggestions", [])) or "- None"

    body = f"""## AI PR Review (Claude)

### Summary
{review.get("summary", "No summary available.")}

### Identified Risks
{risks}

### Improvement Suggestions
{suggestions}

### Confidence: {review.get("confidence", "Unknown")}

---
*Generated by claude-review using Claude Sonnet 4*
"""

    url = f"https://api.github.com/repos/{repo}/issues/{number}/comments"
    data = json.dumps({"body": body}).encode("utf-8")
    req = urllib.request.Request(url, data=data, headers={
        "Content-Type": "application/json",
        "Authorization": f"Bearer {token}",
        "Accept": "application/vnd.github.v3+json",
    })

    with urllib.request.urlopen(req, timeout=30) as resp:
        print(f"Comment posted: {resp.status}")


def main():
    token = os.environ["GITHUB_TOKEN"]
    number = int(os.environ["PR_NUMBER"])
    repo = os.environ["PR_REPO"]

    print(f"Fetching diff for {repo}#{number}...")
    diff = fetch_diff(repo, number, token)

    if not diff.strip():
        print("Diff is empty, posting a note.")
        post_comment(repo, number, token, {
            "summary": "No meaningful changes detected in this PR diff.",
            "risks": [],
            "suggestions": [],
            "confidence": "High",
        })
        return

    print("Calling Claude for review...")
    review = call_claude(diff)

    print("Posting review comment...")
    post_comment(repo, number, token, review)
    print("Done!")


if __name__ == "__main__":
    main()
